package com.novacommerce.order.api; import com.novacommerce.order.application.CheckoutService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1")public class CheckoutController{private final CheckoutService checkout;public CheckoutController(CheckoutService c){checkout=c;}@PostMapping("/checkout")ResponseEntity<CheckoutService.Result>checkout(@AuthenticationPrincipal Jwt j,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid@RequestBody OrderDtos.CheckoutRequest r){var result=checkout.checkout(CartController.owner(j),r.cartId(),key,j.getTokenValue());if(result.retryable())return ResponseEntity.accepted().body(result);return ResponseEntity.status(result.replay()?HttpStatus.OK:HttpStatus.CREATED).body(result);}}
